// Package manifest parses the HLS and DASH playlists generated by the
// fixture generator. Only the small fixture-covered subset is accepted;
// anything outside it (missing duration, illegal sequence numbers,
// duplicate references, remote URIs) is reported as a locatable
// merr.Error instead of being silently repaired.
package manifest

import (
	"math/big"
	"strconv"
	"strings"

	"archivecheck/internal/media"
	"archivecheck/internal/merr"
)

// Format identifiers.
const (
	FormatHLS  = "hls"
	FormatDASH = "dash"
)

// SegmentRef is one segment reference inside a track playlist.
// Duration is kept as an exact rational (seconds = Num/Den) so the
// timeline layer can convert it without float drift.
type SegmentRef struct {
	Seq         uint32
	URI         string
	DurationNum int64
	DurationDen int64
	RawDuration string
}

// DurationRational returns the segment duration as a big.Rat in seconds.
func (r SegmentRef) DurationRational() *big.Rat {
	return new(big.Rat).SetFrac(big.NewInt(r.DurationNum), big.NewInt(r.DurationDen))
}

// Track is one parsed representation / media playlist.
type Track struct {
	ID               uint32
	Name             string
	Kind             media.TrackKind
	Width            uint16
	Height           uint16
	TargetBitrateBps int
	Refs             []SegmentRef
}

// Playlist is the parsed, validated manifest.
type Playlist struct {
	Format             string
	TargetDurationTick int64 // HLS EXT-X-TARGETDURATION, DASH minBufferTime
	Tracks             []*Track
}

// assertLocalURI enforces the read-only, no-remote-download boundary and
// rejects path traversal inside a referenced segment URI.
func assertLocalURI(subsystem, location, uri string) error {
	if uri == "" {
		return merr.New(merr.KindManifest, subsystem, location, "empty segment reference")
	}
	lower := strings.ToLower(uri)
	if strings.HasPrefix(lower, "http://") || strings.HasPrefix(lower, "https://") ||
		strings.HasPrefix(uri, "//") {
		return merr.New(merr.KindManifest, subsystem, location,
			"remote URI is not allowed in offline archive check: "+uri)
	}
	if strings.Contains(lower, "://") {
		return merr.New(merr.KindManifest, subsystem, location,
			"unsupported URI scheme, only local relative references are allowed: "+uri)
	}
	for _, part := range strings.Split(uri, "/") {
		if part == ".." {
			return merr.New(merr.KindManifest, subsystem, location,
				"path traversal is not allowed in segment reference: "+uri)
		}
	}
	return nil
}

// finalizeTrack runs the checks shared by HLS and DASH: monotonic legal
// sequence numbers, local URIs and no duplicate references.
func finalizeTrack(subsystem string, t *Track) error {
	seen := make(map[string]int, len(t.Refs))
	prev := int64(-1)
	for i, ref := range t.Refs {
		loc := ref.Location(subsystem, t.Name)
		if ref.DurationNum <= 0 || ref.DurationDen <= 0 {
			return merr.New(merr.KindManifest, subsystem, loc,
				"segment is missing a positive duration")
		}
		if int64(ref.Seq) <= prev {
			return merr.New(merr.KindManifest, subsystem, loc,
				"illegal segment sequence number, sequence must strictly increase")
		}
		prev = int64(ref.Seq)
		if err := assertLocalURI(subsystem, loc, ref.URI); err != nil {
			return err
		}
		if line, dup := seen[ref.URI]; dup {
			return merr.New(merr.KindManifest, subsystem, loc,
				"duplicate segment reference, already declared at "+itoa(line))
		}
		seen[ref.URI] = i + 1
	}
	if len(t.Refs) == 0 {
		return merr.New(merr.KindManifest, subsystem, "track:"+t.Name,
			"track declares no segments")
	}
	return nil
}

// validate runs whole-playlist checks after parsing.
func validate(p *Playlist) error {
	if len(p.Tracks) == 0 {
		return merr.New(merr.KindManifest, p.Format, "playlist",
			"manifest declares no tracks")
	}
	names := map[string]bool{}
	for _, t := range p.Tracks {
		if t.Name == "" {
			return merr.New(merr.KindManifest, p.Format, "playlist",
				"track without a name/id")
		}
		if names[t.Name] {
			return merr.New(merr.KindManifest, p.Format, "track:"+t.Name,
				"duplicate track identifier")
		}
		names[t.Name] = true
		if t.TargetBitrateBps <= 0 {
			return merr.New(merr.KindManifest, p.Format, "track:"+t.Name,
				"missing or non-positive target bitrate")
		}
		sub := p.Format + ":track:" + t.Name
		if err := finalizeTrack(sub, t); err != nil {
			return err
		}
	}
	return nil
}

// Location renders a parse-error locator for a segment reference.
func (r SegmentRef) Location(subsystem, track string) string {
	return subsystem + ":track:" + track + ":seq:" + itoa(int(r.Seq))
}

func itoa(i int) string { return strconv.Itoa(i) }
